export async function readSystemHosts(options, hostOverride) {
    const res = await callHostTransport('dllplugin_call', {
        plugin: 'HostsSwitcherPlugin',
        func: 'readSystemHosts',
        params: options || {}
    }, hostOverride);
    if (res.ok && typeof res.data?.content === 'string') {
        return { ok: true, content: res.data.content, path: res.data.path };
    }
    return { ok: false, content: '' };
}
export async function applyCombinedHosts(content, options, hostOverride) {
    const res = await callHostTransport('dllplugin_call', {
        plugin: 'HostsSwitcherPlugin',
        func: 'applyCombinedHosts',
        params: {
            content,
            ...options
        }
    }, hostOverride);
    if (!res.ok) {
        return {
            success: false,
            errorCode: res.data?.errorCode || 'EACCES',
            error: res.error || res.data?.error || '写入系统 hosts 失败'
        };
    }
    return { success: true };
}
export async function flushDnsCache(options, hostOverride) {
    const res = await callHostTransport('dllplugin_call', {
        plugin: 'HostsSwitcherPlugin',
        func: 'flushDns',
        params: options || {}
    }, hostOverride);
    if (!res.ok) {
        return {
            success: false,
            output: '',
            error: res.error || res.data?.error || '刷新 DNS 缓存失败'
        };
    }
    return {
        success: true,
        output: res.data?.output || '本地 DNS 缓存已成功刷新'
    };
}
